insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('logos','logos',true,5242880,array['image/jpeg','image/png','image/webp']),('covers','covers',true,5242880,array['image/jpeg','image/png','image/webp'])
on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy flek_images_read on storage.objects for select using(bucket_id in ('logos','covers'));
create policy flek_images_insert on storage.objects for insert to authenticated with check(bucket_id in ('logos','covers') and exists(select 1 from public.business_members m where m.user_id=auth.uid() and m.business_id::text=(storage.foldername(name))[1]));
create policy flek_images_update on storage.objects for update to authenticated using(bucket_id in ('logos','covers') and exists(select 1 from public.business_members m where m.user_id=auth.uid() and m.business_id::text=(storage.foldername(name))[1])) with check(bucket_id in ('logos','covers') and exists(select 1 from public.business_members m where m.user_id=auth.uid() and m.business_id::text=(storage.foldername(name))[1]));
create policy flek_images_delete on storage.objects for delete to authenticated using(bucket_id in ('logos','covers') and exists(select 1 from public.business_members m where m.user_id=auth.uid() and m.business_id::text=(storage.foldername(name))[1]));
